// #region 🔖OntologyTree
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖ontologytree](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/OntologyTree)
// Tree viewer for visualizing OWL class expression structure (schema-level, no instances).
// OntologyTree MUST render a collapsible tree of the class expression without truth values.

/**
 * Node kind in an ontology class expression tree.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖ontologytree✂️ontologynodekind](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/OntologyTree/d/f/OntologyNodeKind)
 *Enumerates all OWL class expression constructs.
 **/
type OntologyNodeKind =
  | "Class"
  | "And"
  | "Or"
  | "Not"
  | "SomeValuesFrom"
  | "AllValuesFrom"
  | "ExactCardinality"
  | "MinCardinality"
  | "MaxCardinality"
  | "DataSomeValuesFrom"
  | "DataAllValuesFrom"
  | "DataHasValue"
  | "DatatypeRestriction";

/**
 * A node in the ontology class expression tree (schema only, no instances).
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖ontologytree✂️ontologytreenode](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/OntologyTree/d/f/OntologyTreeNode)
 *MUST have id, kind, label, and children.
 **/
interface OntologyTreeNode {
  id: string;
  kind: OntologyNodeKind;
  label: string;
  fragment?: string;
  property?: string;
  className?: string;
  cardinality?: number;
  datatype?: string;
  restriction?: string;
  children: OntologyTreeNode[];
}

/**
 * Returns the icon label for an ontology node kind.
 **/
function ontologyNodeIcon(kind: OntologyNodeKind): string {
  switch (kind) {
    case "Class": return "C";
    case "And": return "∧";
    case "Or": return "∨";
    case "Not": return "¬";
    case "SomeValuesFrom": return "∃";
    case "AllValuesFrom": return "∀";
    case "ExactCardinality": return "=n";
    case "MinCardinality": return "≥n";
    case "MaxCardinality": return "≤n";
    case "DataSomeValuesFrom": return "∃d";
    case "DataAllValuesFrom": return "∀d";
    case "DataHasValue": return "v";
    case "DatatypeRestriction": return "D";
    default: return "?";
  }
}

function getOntologyNodeDescriptor(node: OntologyTreeNode): { icon: string; primaryText: string; secondaryText?: string } {
  return {
    icon: ontologyNodeIcon(node.kind),
    primaryText: node.label,
    secondaryText: node.fragment && node.fragment !== node.label ? node.fragment : undefined,
  };
}

/**
 * Renders a single ontology tree node with expand/collapse.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖ontologytree🛠️ontologytreenodeview](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/OntologyTree/d/i/OntologyTreeNodeView)
 *MUST display the node kind icon, label, and expandable children.
 **/
function OntologyTreeNodeView({
  node,
  defaultExpanded = true,
}: {
  node: OntologyTreeNode;
  defaultExpanded?: boolean;
}) {
  const descriptor = getOntologyNodeDescriptor(node);

  return (
    <TreeItem
      id={node.id}
      defaultOpen={defaultExpanded}
      label={(
        <span className="flex min-w-0 flex-col gap-0.5 py-0.5">
          <span className="flex min-w-0 items-center gap-2">
            <span className="inline-flex items-center justify-center h-5 min-w-5 rounded bg-info-bg px-1 text-[10px] font-bold text-info-foreground shrink-0" title={node.kind}>
              {descriptor.icon}
            </span>
            <span className="min-w-0 truncate text-sm font-medium text-foreground">{descriptor.primaryText}</span>
          </span>
          {descriptor.secondaryText && (
            <span className="pl-7 text-[11px] text-muted-foreground">{descriptor.secondaryText}</span>
          )}
        </span>
      )}
    >
      {node.children.map((child) => (
        <OntologyTreeNodeView key={child.id} node={child} defaultExpanded={defaultExpanded} />
      ))}
    </TreeItem>
  );
}

/**
 * Tree viewer that displays an OWL class expression as a collapsible tree.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖ontologytree🛠️ontologytree](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/OntologyTree/d/i/OntologyTree)
 *MUST render the full ontology tree structure from root.
 **/
function OntologyTree({
  root,
  title,
  defaultExpanded = true,
}: {
  root: OntologyTreeNode;
  title?: string;
  defaultExpanded?: boolean;
}) {
  return (
    <div className="rounded-lg border border-border-window bg-window overflow-hidden">
      {title && (
        <div className="border-b border-border-window px-3 py-2">
          <h3 className="text-sm font-semibold text-foreground">{title}</h3>
        </div>
      )}
      <div className="p-2 overflow-x-auto">
        <Tree className="min-w-0" sections={[{ id: "ontology-root", label: null, content: <OntologyTreeNodeView node={root} defaultExpanded={defaultExpanded} /> }]} />
      </div>
    </div>
  );
}

// #endregion 🔖OntologyTree

// #region 🔖ValidationTree
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖validationtree](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/ValidationTree)
// Tree viewer for visualizing validation results (data graph instances of the ontology).
// ValidationTree MUST render truth values, witnesses, data values, and cardinality info.

/**
 * Three-valued truth for validation nodes.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖validationtree✂️truthvalue](semiorepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/ValidationTree/d/f/TruthValue)

          onDoubleClick={(event) => {
            if (!onDoubleClick) return;
            event.preventDefault();
            event.stopPropagation();
            onDoubleClick(event);
          }}
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
        >
          <IndentationLines level={level} isLastAtLevel={isLastAtLevel} showLines={showLines} />
          <button
            className="flex-shrink-0 p-0 border-0 bg-transparent cursor-foldable"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              setOpen(!open);
            }}
          >
            {open ? <ChevronDownIcon className="size-[14px] flex-shrink-0" /> : <ChevronRightIcon className="size-[14px] flex-shrink-0" />}
          </button>
          {isDragHandle && <Action className="cursor-grab active:cursor-grabbing" {...attributes} {...listeners} onClick={(e) => e.stopPropagation()} icon={<GripVerticalIcon size={12} className="text-muted-foreground" />} />}
          {icon && <span className="flex items-center justify-center flex-shrink-0">{icon}</span>}
          <span
            data-slot="tree-label"
            className="flex-1 text-xs font-normal truncate text-foreground cursor-selectable"
            onClick={(e) => {
              if (e.detail > 1) return;
              e.preventDefault();
              e.stopPropagation();
              onClick?.(e);
            }}
          >
            {displayLabel as React.ReactNode}
          </span>
          {actions.length > 0 && (
            <div className="flex items-center gap-single">
              {actions.map((action, index) => (
                <Action
                  key={index}
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    action.onClick();
                  }}
                  id={action.id}
                  icon={action.icon}
                />
              ))}
            </div>
          )}
        </div>
        {open && (
          <TreeContext.Provider value={{ level: level + 1, isLastAtLevel: [...isLastAtLevel, isLastItem], showLines, isTree }}>
            <div className="flex flex-col gap-y-[2px]">{children}</div>
          </TreeContext.Provider>
        )}
      </>
    );
  }

  if (!displayLabel) {
    return <TreeContext.Provider value={{ level, isLastAtLevel, showLines, isTree }}>{children}</TreeContext.Provider>;
  }

  return (
    <div
      data-slot="tree-item-row"
      role="treeitem"
      id={id}
      ref={setNodeRef}
      style={style}
      className={itemClasses}
      onClick={(event) => {
        if (event.detail > 1) return;
        onClick?.(event);
      }}
      onDoubleClick={(event) => {
        if (!onDoubleClick) return;
        event.preventDefault();
        event.stopPropagation();
        onDoubleClick(event);
      }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <IndentationLines level={level} isLastAtLevel={isLastAtLevel} showLines={showLines} />
      <div className="w-[14px] flex-shrink-0" />
      {isDragHandle && <Action className="cursor-grab active:cursor-grabbing" {...attributes} {...listeners} icon={<GripVerticalIcon size={12} className="text-muted-foreground" />} />}
      {icon && <span className="flex items-center justify-center flex-shrink-0">{icon}</span>}
      <span data-slot="tree-label" className="flex-1 text-xs font-normal truncate text-foreground">
        {displayLabel as React.ReactNode}
      </span>
      {actions.length > 0 && (
        <div className="flex items-center gap-single">
          {actions.map((action, index) => (
            <Action
              key={index}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                action.onClick();
              }}
              id={action.id}
              icon={action.icon}
            />
          ))}
        </div>
      )}
    </div>
  );
};

/**
 * Drag-and-drop sortable container for tree items.
 * [👤semio📚js🗃️sketchpad💻elements🔖tree🪨sortabletreeitems](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/elements.tsx/s/Tree/d/i/SortableTreeItems)
 **/
export const SortableTreeItems: React.FC<SortableTreeItemsProps> = ({ items, onReorder, children }) => {
  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      const oldIndex = items.findIndex((item) => item.id === active.id);
      const newIndex = items.findIndex((item) => item.id === over.id);
      if (oldIndex !== -1 && newIndex !== -1) {
        onReorder(oldIndex, newIndex);
      }
    }
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <SortableContext items={items.map((item) => item.id)} strategy={verticalListSortingStrategy}>
        {items.map((item, index) => children(item, index))}
      </SortableContext>
    </DndContext>
  );
};

/**
 * Single tree item row with icon, label, and interaction handlers.
 * [👤semio📚js🗃️sketchpad💻elements🔖tree🪨treeitem](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/elements.tsx/s/Tree/d/i/TreeItem)
 **/
export const TreeItem: React.FC<TreeItemProps> = ({
  label,
  id,
  icon,
  children,
  onClick,
  className = "",
  isSelected = false,
  isHighlighted = false,
  sortable = false,
  sortableId,
  isDragHandle = false,
  defaultOpen = true,
