                        )}
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-xs text-muted-foreground">No measure instructions.</p>
                )}
              </Collapsible>
            ))}
          </div>
        ) : (
          <EmptyState message="No platforms configured." />
        )}
      </Card>
    </div>
  );
